INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0V7B2N4NR2AFQPFYKVT7997', '0', '# Major Releases');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0V7B2N4NR2AFQPFYKVT7997', '1', '');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0V7B2N4NR2AFQPFYKVT7997', '2', 'Forward-looking planning ledger for major releases — one block per release, minimal fields, blank');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0V7B2N4NR2AFQPFYKVT7997', '3', 'line between blocks. Marathon plans and other forward planning cross-reference this doc for');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0V7B2N4NR2AFQPFYKVT7997', '4', 'target release names/dates; it is not a history of what shipped (that''s CHANGELOG.md — lessons');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0V7B2N4NR2AFQPFYKVT7997', '5', 'learned belong there at ship time, not duplicated here). Contract lives in PROJECT/PDDA.md ->');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0V7B2N4NR2AFQPFYKVT7997', '6', '"RELEASES.md — release ledger". Add new fields only when a real need shows up.');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0V7B2N4NR2AFQPFYKVT7997', '7', '');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0V7B2N4NR2AFQPFYKVT7997', '8', '**Versions are RECORDED, never RESERVED (recalibrated 2026-08-17).** `Release:` reads `TBD` until a');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0V7B2N4NR2AFQPFYKVT7997', '9', 'release''s last issue closes, then records the version where that actually happened. The `Iterations:`');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0V7B2N4NR2AFQPFYKVT7997', '10', 'band field is retired on live blocks and must not be re-added: it predicted which theme the next N');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0V7B2N4NR2AFQPFYKVT7997', '11', 'version slots would belong to, and across 1.4.278–1.4.295 — eighteen consecutive slots — it was wrong');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0V7B2N4NR2AFQPFYKVT7997', '12', 'every time, because this team ships whatever is urgent and deploys ad-hoc rather than by release. Two');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0V7B2N4NR2AFQPFYKVT7997', '13', 'of the three banded releases had their bands pass entirely into history with zero issues shipped. The');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0V7B2N4NR2AFQPFYKVT7997', '14', '"Band corrected" and "Sequencing deviation" notes below are the overhead that field produced; they are');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0V7B2N4NR2AFQPFYKVT7997', '15', 'kept as history, not as a pattern to continue. A release closes when its issues close. The version');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0V7B2N4NR2AFQPFYKVT7997', '16', 'number is a monotonic counter of CHANGELOG headings and belongs to no one.');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0V7B2N4NR2AFQPFYKVT7997', '17', '');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ2JRKQABYXPP3VEYB8', '24', 'Issues: #80 frozen manifest · #79 charter/rule · #77, #66 moot under one path · #74 canonical');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ2JRKQABYXPP3VEYB8', '25', '  (option 2), #73 superseded · #75, #76 ride along');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ2JRKQABYXPP3VEYB8', '26', 'Issues frozen: 2026-08-17 in #80. Scope changes by succeeding that issue, not by editing it.');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ2JRKQABYXPP3VEYB8', '27', 'Not in scope: #67 (ships on its own, first — live echo-loop risk), #51 (blocked on GH-50 corpus)');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ2JRKQABYXPP3VEYB8', '28', 'Deploys: ad-hoc to dev/production as work lands. This block is a bookkeeping unit, NOT a deploy gate.');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ2JRKQABYXPP3VEYB8', '33', '  "Ledger" block above had to be corrected for describing declined work as pending, so the');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ2JRKQABYXPP3VEYB8', '34', '  narrative lives on the issues where it can be closed, not here where it goes stale.');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ2JRKQABYXPP3VEYB8', '35', '  Version DELIBERATELY unassigned per the recording rule at the top of this file. A minor bump is');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ2JRKQABYXPP3VEYB8', '36', '  likely earned — the user-visible default changes for everyone (verbatim display is deleted, not');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ2JRKQABYXPP3VEYB8', '37', '  retuned) — and 1.5.0 was left FREE by the Ledger block. Decide that when it ships, not now:');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ2JRKQABYXPP3VEYB8', '38', '  1.5.0 has already been burned once as a reservation that was never consumed.');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ3JJBA7BKJ1B0X4XV2', '43', 'Shakdedown reviwed: No');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ3JJBA7BKJ1B0X4XV2', '45', 'Deadline: July 25, 2026');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ3M2QS60XDJ0JE0324', '49', 'Iterations: 1.5.0-1.5.9');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ3M2QS60XDJ0JE0324', '53', '  projection/research substrate, and that is the settled end state');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ3M2QS60XDJ0JE0324', '56', 'Issues: (none open) — #35 P3 Phase 5 close-out, CLOSED');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ3M2QS60XDJ0JE0324', '57', 'Version NOT consumed: 1.5.0 was a forward RESERVATION for a minor-version-worthy capability');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ3M2QS60XDJ0JE0324', '58', '  (the log becoming authoritative). That capability was declined, so 1.5.0 was never spent —');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ3M2QS60XDJ0JE0324', '59', '  zero 1.5.x entries in CHANGELOG.md, and this repo has zero git tags, so versions exist only');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ3M2QS60XDJ0JE0324', '60', '  as CHANGELOG headings. 1.5.0 is therefore FREE for whatever genuinely earns a minor bump.');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ3M2QS60XDJ0JE0324', '61', '  The P3 work itself shipped incrementally through the 1.4.2xx line and closed at 1.4.270 —');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ3M2QS60XDJ0JE0324', '62', '  which is why this block''s number reads higher than releases that came after it. It is');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ3M2QS60XDJ0JE0324', '63', '  aspirational, not chronological.');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ3M2QS60XDJ0JE0324', '64', 'Issues frozen: 2026-08-14. This block was STALE and is corrected here. It read Status: Draft');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ3M2QS60XDJ0JE0324', '65', '  with a milestone of "the log is authoritative", describing work that had already been');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ3M2QS60XDJ0JE0324', '66', '  consciously declined. Do not re-open it as a goal without the product decision below.');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ3M2QS60XDJ0JE0324', '71', '  2026-08-09 (PROJECT/3-COMPLETED/P3-EVENT-SOURCED-CORE.md). Phases 0-3 delivered: the');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ3M2QS60XDJ0JE0324', '72', '  append-only per-workspace ledger, the reminder-domain event types, the projections, the');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ3M2QS60XDJ0JE0324', '73', '  entity-linking read-model, and the GH-355 baseline import that took the prod shadow-diff');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ3M2QS60XDJ0JE0324', '74', '  from 11 mismatches to 0.');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ3M2QS60XDJ0JE0324', '75', '  The authority flip did NOT happen, and that is a DECISION rather than an unfinished task.');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ3M2QS60XDJ0JE0324', '76', '  Generation-binding of the coverage marker was FALSIFIED: a crashed append writes nothing');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ3M2QS60XDJ0JE0324', '77', '  to the ledger, so no ledger-derived quantity can distinguish "no append was attempted"');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ3M2QS60XDJ0JE0324', '78', '  from "an append was lost" — and completeness is exactly what serving a projection');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ3M2QS60XDJ0JE0324', '79', '  requires. The two candidate read surfaces were also found to gain migration confidence');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ3M2QS60XDJ0JE0324', '80', '  but no latency or scale benefit. So the ledger is retained as a NON-AUTHORITATIVE');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ3M2QS60XDJ0JE0324', '81', '  projection/research substrate: not audit-grade, and explicitly not a deferred authority');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ3M2QS60XDJ0JE0324', '82', '  migration waiting for a later release.');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ3M2QS60XDJ0JE0324', '83', '  This is enforced in CODE, not merely config. src/reminders-projection.js blocks all four');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ3M2QS60XDJ0JE0324', '84', '  projection flags (REMINDERS_READ_SOURCE, COMPLETED_READ_SOURCE, REBALANCE_EXPORT_SOURCE,');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ3M2QS60XDJ0JE0324', '85', '  SUMMARIZE_WEEK_COMPLETED_SOURCE) at compile time, because config alone left a live path');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ3M2QS60XDJ0JE0324', '86', '  from a routine parity-harness run straight to a production cutover with no deploy and no');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ3M2QS60XDJ0JE0324', '87', '  review. REMINDER_STATE_SOURCE is absent from src/ by design, not by omission.');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ3M2QS60XDJ0JE0324', '88', '  WHAT WOULD RE-OPEN IT: a named product consumer plus a fresh proposal — a product');
