INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ4KMFQ8KXASJJK02WB', '100', 'Band retired: 2026-08-17. Was 1.4.278-1.4.279 (itself a correction from 1.4.270-1.4.279). Both');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ4KMFQ8KXASJJK02WB', '101', '  slots passed into history with ZERO Roundup issues shipped; see the versioning rule at the top.');
