INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ4KMFQ8KXASJJK02WB', '126', '  no longer what it is. GH-22 (multiple reminder assignees), the only user-visible defect');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ4KMFQ8KXASJJK02WB', '127', '  it carried, SHIPPED in 1.4.264 via PR #29 and is closed. What remains is entirely tooling');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ4KMFQ8KXASJJK02WB', '128', '  — four checks and one script that are broken in a way which makes OTHER problems harder');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ4KMFQ8KXASJJK02WB', '129', '  to see. That is now the whole point of the release, so the milestone reads honestly.');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ4KMFQ8KXASJJK02WB', '130', '  The unifying defect: a check that is always red, always warning, or silently skipping');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ4KMFQ8KXASJJK02WB', '131', '  teaches people to ignore it, and then it can never signal the condition it exists for.');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ4KMFQ8KXASJJK02WB', '132', '  GH-39 (`validate:commands` permanently red on development — ask-reminders is registered');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ4KMFQ8KXASJJK02WB', '133', '  dynamically and invisible to the static scan) and GH-41 (`validate:ai` silently skips any');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ4KMFQ8KXASJJK02WB', '134', '  prompt asset missing from its hardcoded EXPECTED_PAIRS map, so a new prompt pair is');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ4KMFQ8KXASJJK02WB', '135', '  unvalidated until someone remembers to add it) are the two worst, because both fail');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ4KMFQ8KXASJJK02WB', '136', '  SILENTLY in the direction of false confidence. Both were open and assigned to NO release');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ4KMFQ8KXASJJK02WB', '137', '  before this reconciliation.');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ4KMFQ8KXASJJK02WB', '138', '  GH-26 (RELEASES.md <!--test--> fixture errors every releases check, plus Codename');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ4KMFQ8KXASJJK02WB', '139', '  absorbed by the preceding block) is the highest-leverage of the four and is this');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ4KMFQ8KXASJJK02WB', '140', '  release''s anchor: it is what keeps `pdda.sh releases` from ever reaching errors=0, which');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ4KMFQ8KXASJJK02WB', '141', '  in turn skips `pdda-doc-ready` ENTIRELY. Note that `utils/pdda/*` is synced from a');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ4KMFQ8KXASJJK02WB', '142', '  canonical PDDA repo, so the fix must be pushed upstream or the next `pdda-sync.sh push`');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ4KMFQ8KXASJJK02WB', '143', '  overwrites it. GH-25 (sanitize-scan.sh cannot run from a linked git worktree —');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ4KMFQ8KXASJJK02WB', '144', '  `[ -d .git ]` is false when .git is a file) blocks running the secret/PII gate locally');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ4KMFQ8KXASJJK02WB', '145', '  before pushing; CI is unaffected, so the cost is a slower feedback loop, not an exposure.');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ4KMFQ8KXASJJK02WB', '146', '  Closed during this reconciliation, with evidence, rather than carried as open scope:');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ4KMFQ8KXASJJK02WB', '147', '  GH-40 (changelog parser misread) — the parser now reports the top heading''s date exactly,');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ4KMFQ8KXASJJK02WB', '148', '  and the warning that remains is the check correctly signalling a missing entry. GH-42');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ4KMFQ8KXASJJK02WB', '149', '  (vendored .xyz harness stale) — synced to 824d9388417c; every /relay-xyz QA in this repo');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ4KMFQ8KXASJJK02WB', '150', '  had been running on stale harness code until then.');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ4KMFQ8KXASJJK02WB', '151', '  Deliberately NOT included: the snapshot->Slack relay missing_scope failure (see');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ4KMFQ8KXASJJK02WB', '152', '  PROJECT/2-WORKING/P2-SNAPSHOT-SLACK-RELAY.md). It is real and live since 2026-06-18, but');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ4KMFQ8KXASJJK02WB', '153', '  the fix is a Slack app admin re-granting a file-upload scope — an ops action with no code');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ4KMFQ8KXASJJK02WB', '154', '  change, so it cannot be a marathon phase.');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ4KMFQ8KXASJJK02WB', '155', '  Done when: GH-25, GH-26, GH-39 and GH-41 are closed; `pdda.sh releases` reports errors=0');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ4KMFQ8KXASJJK02WB', '156', '  and `pdda-doc-ready` actually runs; `validate:commands` and `validate:ai` are green and');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ4KMFQ8KXASJJK02WB', '157', '  provably able to FAIL (a check that cannot fail proves nothing); and the full suite is');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ4KMFQ8KXASJJK02WB', '158', '  green.');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ4KMFQ8KXASJJK02WB', '159', '  Plan: PROJECT/2-WORKING/GH-26-RELEASES-PARSING.md');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ4KMFQ8KXASJJK02WB', '160', '  Sequencing note: Roundup ships FIRST (1.4.278-279), before Grounding (1.4.280) and Antecedent');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ4KMFQ8KXASJJK02WB', '161', '    (1.4.290). Deliberate — GH-39 and GH-41 are the checks that would otherwise let a defect in');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ4KMFQ8KXASJJK02WB', '162', '    those two releases pass unnoticed. Fix the instruments before running the experiments.');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ4ZFWJ1K27PBGPH4AY', '164', 'Band retired: 2026-08-17. Was 1.4.280-1.4.289; the band passed entirely with #51 still open.');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ4ZFWJ1K27PBGPH4AY', '166', '  UNOWNED AND UNFILED (stated in this block''s own Description). That policy is the real blocker.');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ4ZFWJ1K27PBGPH4AY', '171', 'Issues: #51');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ4ZFWJ1K27PBGPH4AY', '172', 'Issues frozen: 2026-08-14.');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ4ZFWJ1K27PBGPH4AY', '177', '  parsing work this session opened with. Measured against 30 days of production telemetry:');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ4ZFWJ1K27PBGPH4AY', '178', '  128 of 216 scheduled messages (60%) log actionable_span_ratio=0 — the analyzer quoted NO');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ4ZFWJ1K27PBGPH4AY', '179', '  actionable span for the message it had just decided to schedule. 48 of those are 400+');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ4ZFWJ1K27PBGPH4AY', '180', '  characters; the largest is 6998. On every one of them the GH-43 buried-task gate is inert');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ4ZFWJ1K27PBGPH4AY', '181', '  by design, because a zero ratio is absence of evidence rather than evidence of a buried');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ4ZFWJ1K27PBGPH4AY', '182', '  task, so a very long note routes on sentence count alone.');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ4ZFWJ1K27PBGPH4AY', '183', '  What already shipped, and why it is NOT this: GH-43 (1.4.273-274) fixed synthesis routing');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ4ZFWJ1K27PBGPH4AY', '184', '  and ownership; GH-51 (1.4.277) fixed a rounding defect where toFixed(2) collapsed any span');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ4ZFWJ1K27PBGPH4AY', '185', '  under 0.5% of the message to exactly 0, hiding the most deeply buried task of all. That');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ4ZFWJ1K27PBGPH4AY', '186', '  rounding fix is real but explains AT MOST 1 of the 128 — the median zero-ratio message is');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ4ZFWJ1K27PBGPH4AY', '187', '  241 characters, where nothing rounds away. The remaining ~127 are the analyzer returning an');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ4ZFWJ1K27PBGPH4AY', '188', '  empty actionable_language. The schema already requires the field (strict: true), so the');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ4ZFWJ1K27PBGPH4AY', '189', '  model is satisfying presence with "", and OpenAI strict mode has no minLength to forbid it.');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ4ZFWJ1K27PBGPH4AY', '190', '  Deliberately NOT started by editing reminders-instructions.md on a hypothesis. The decision');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ4ZFWJ1K27PBGPH4AY', '191', '  corpus wired in GH-50 (1.4.276) exists precisely so this can be diagnosed from real');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ4ZFWJ1K27PBGPH4AY', '192', '  input/output pairs rather than guessed at — but it is default-OFF and carries raw tenant');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ4ZFWJ1K27PBGPH4AY', '193', '  text with no rotation, cap, or expiry, so a retention policy is a hard prerequisite before');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ4ZFWJ1K27PBGPH4AY', '194', '  it is armed anywhere real. That policy is currently unowned and unfiled.');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ4ZFWJ1K27PBGPH4AY', '195', '  Done when: the ratio=0 share is explained with evidence rather than inference (schema,');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ4ZFWJ1K27PBGPH4AY', '196', '  prompt, structural path, or a measurement bug); any extraction defect found is fixed with a');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ4ZFWJ1K27PBGPH4AY', '197', '  regression test built from real production shapes; and the share is re-measured on');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ4ZFWJ1K27PBGPH4AY', '198', '  production traffic with the before/after recorded.');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ4ZFWJ1K27PBGPH4AY', '199', '  Plan: PROJECT/2-WORKING/ (to be written when the corpus is armed)');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ46K0PJ61KY2HPV9VV', '202', 'Band retired: 2026-08-17. Was 1.4.290-1.4.299; 1.4.291-1.4.296 went to unrelated work.');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ46K0PJ61KY2HPV9VV', '204', '  when the flag is armed and the milestone is observed in production, not on merge.');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ46K0PJ61KY2HPV9VV', '205', 'Sequencing deviation: 2026-08-14. Roundup''s note below says Roundup ships FIRST. It did not — GH-55');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ46K0PJ61KY2HPV9VV', '206', '  was implemented and merged before any Roundup issue shipped. Recorded rather than quietly');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ46K0PJ61KY2HPV9VV', '207', '  renumbered, because this is the NINTH consecutive version slot to go to work outside the release');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ46K0PJ61KY2HPV9VV', '208', '  that reserved it. Antecedent took 1.4.290 from its OWN band precisely so it did not become the');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ46K0PJ61KY2HPV9VV', '209', '  ninth theft of Roundup''s: 1.4.278-1.4.279 remain unspent and Roundup''s band is intact.');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ46K0PJ61KY2HPV9VV', '210', '  The sequencing rationale ("fix the instruments before running the experiments") does not apply');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ46K0PJ61KY2HPV9VV', '211', '  here — GH-39/GH-41 are RELEASES/changelog parsing checks, and nothing in this work was verified');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ46K0PJ61KY2HPV9VV', '212', '  by them. It was verified by its own instrument: a 9-case noise corpus and five mutations.');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ46K0PJ61KY2HPV9VV', '217', 'Issues: #55');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ46K0PJ61KY2HPV9VV', '218', 'Issues frozen: 2026-08-14.');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ46K0PJ61KY2HPV9VV', '223', '  Monday?", the reminder currently records that literal sentence — the task it points at is');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ46K0PJ61KY2HPV9VV', '224', '  never read, and the owner is lost with it. Observed live 2026-08-14: a follow-up to');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ46K0PJ61KY2HPV9VV', '225', '  "@Vishal please make the fast-search GH issue and work on it" scheduled the string "Can we');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ46K0PJ61KY2HPV9VV', '226', '  try to get it done by end of day on Monday?" and assigned it to the sender rather than');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ46K0PJ61KY2HPV9VV', '227', '  Vishal. Telemetry confirms the analyzer behaved correctly on the text it was handed');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ46K0PJ61KY2HPV9VV', '228', '  (ratio_usable=yes, analyzer_owner=unclear, resolved_by=sender-fallback) — it was handed the');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ46K0PJ61KY2HPV9VV', '229', '  wrong text.');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ46K0PJ61KY2HPV9VV', '230', '  This is the inverse of GH-43/GH-51, which decide whether to SHORTEN a long message; here a');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ46K0PJ61KY2HPV9VV', '231', '  50-character message needs context ADDED. The wrong assignee is the same root cause rather');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ46K0PJ61KY2HPV9VV', '232', '  than a second defect: "can we get it done" has no grammatical subject to own, so ownership');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ46K0PJ61KY2HPV9VV', '233', '  correctly fell back to the sender, and the real owner is only recoverable from the');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ46K0PJ61KY2HPV9VV', '234', '  antecedent. Fixing the antecedent fixes ownership — but NOT "for free", as an earlier draft of');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ46K0PJ61KY2HPV9VV', '235', '  this block claimed: ownership rides on reminder-ownership.js''s mentions fallback, which assigns to');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ46K0PJ61KY2HPV9VV', '236', '  EVERY mention it finds. It resolves correctly in the reported case only because the enriched block');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ46K0PJ61KY2HPV9VV', '237', '  happens to carry exactly one. Enrichment therefore changes the input to the ownership resolver,');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ46K0PJ61KY2HPV9VV', '238', '  which is a second-order effect of a change framed as "text only".');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ46K0PJ61KY2HPV9VV', '239', '  Two blockers, both verified: enrichment is gated on thread_ts and these were top-level');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ46K0PJ61KY2HPV9VV', '240', '  channel posts (enrichment=none is a hardcoded literal on the auto-schedule path), and');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ46K0PJ61KY2HPV9VV', '241', '  "get it done" matches none of the three vague-reference patterns. Deliberately NOT fixed by');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ46K0PJ61KY2HPV9VV', '242', '  adding a verb to the enumerated list — that list is documented in-code as a losing');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ46K0PJ61KY2HPV9VV', '243', '  whack-a-mole (GH-424 needed two rounds and "see above" still slipped through). The general');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ46K0PJ61KY2HPV9VV', '244', '  rule is grammatical: an unresolved pronoun plus a scheduling trigger means the task is');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ46K0PJ61KY2HPV9VV', '245', '  elsewhere, whatever verb surrounds it.');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ46K0PJ61KY2HPV9VV', '246', '  Shipped as ONE change set, not two gated phases. The two-phase split was removed on operator');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ46K0PJ61KY2HPV9VV', '247', '  review as ceremony for a single-maintainer project, and its stated justification — containing the');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ46K0PJ61KY2HPV9VV', '248', '  blast radius of a false positive — did not survive checking against the code: GH-43''s grounding');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ46K0PJ61KY2HPV9VV', '249', '  constraint (reminder-display-selection.js) already DISCARDS a synthesized title naming anything');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ46K0PJ61KY2HPV9VV', '250', '  absent from the source, so a false positive costs one AI call and a possibly noisy context line,');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ46K0PJ61KY2HPV9VV', '251', '  not a wrong reminder. The one risk that does survive is mis-stitching, because enrichment WIDENS');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ46K0PJ61KY2HPV9VV', '252', '  the grounding source — which is what participant continuity exists to contain.');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ46K0PJ61KY2HPV9VV', '253', '  Nothing here touches the analyzer prompt or schema. That keeps the GH-44 battery valid as a');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ46K0PJ61KY2HPV9VV', '254', '  REGRESSION GUARD — but not as a measuring stick: it exercises single-message routing with no');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ46K0PJ61KY2HPV9VV', '255', '  thread context, so it never reaches the enrichment path and cannot show the improvement. A green');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ46K0PJ61KY2HPV9VV', '256', '  battery is not evidence this works.');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ46K0PJ61KY2HPV9VV', '257', '  Done when: the flag is armed in production, a pronoun follow-up in a monitored channel schedules');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ46K0PJ61KY2HPV9VV', '258', '  the real task with the real owner, `enrichedFrom` is present on those events, the GH-44 battery');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ46K0PJ61KY2HPV9VV', '259', '  shows no regression, and GH-55 is closed. NOT met by the 1.4.290 merge: the channel half — the');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ46K0PJ61KY2HPV9VV', '260', '  half that fixes the reported case — is default-OFF until an operator arms it.');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ46K0PJ61KY2HPV9VV', '261', '  Plan: PROJECT/2-WORKING/GH-55-ANTECEDENT-RESOLUTION.md');
