INSERT INTO grandfather_entries(import_run, release_gid, rule, source_value, supplied_value, disposition) VALUES('imp-20260825T011024-dcea2e', 'rel-01M0V7FVJ3M2QS60XDJ0JE0324', 'status-enum', 'Closed — concluded 2026-08-09 WITHOUT the authority flip, by decision', 'active', NULL);
